// 模拟官网同版本 Vue 背包组件，所有物品和操作均为测试数据。
const {createApp,defineComponent,h,ref,computed,reactive,watch,Fragment}=Vue;
const initial=window.backpackFixture;
const state=reactive(initial),show=ref(true),actions=[];window.backpackOwner=state;window.backpackActions=actions;window.showBackpack=value=>show.value=value;
const VPagination=defineComponent({name:'VPagination',props:['modelValue','length'],emits:['update:modelValue'],setup(props,{emit}){return()=>h('nav',{class:'bag-pagination'},Array.from({length:props.length},(_,index)=>h('button',{'aria-label':'第'+(index+1)+'页','aria-current':props.modelValue===index+1?'page':null,onClick:()=>emit('update:modelValue',index+1)},String(index+1))));}});
const VTooltip=defineComponent({name:'VTooltip',props:['item','kind','selling'],setup(props){const visible=ref(false);return()=>h(Fragment,[h('div',{class:'bag-grid-item',onMouseenter:()=>visible.value=true,onMouseleave:()=>visible.value=false,onClick:()=>actions.push({action:props.selling?'sell-select':props.kind==='equipment'?'equip':'use',uuid:props.item.uuid})},[h('span',{class:'test-item-name'},props.item.name)]),visible.value?h(Vue.Teleport,{to:'body'},h('div',{class:'equip-tooltip-surface'},h('div',{class:'equip-tooltip'},[h('strong','+'+props.item.reinforce_level+' '+props.item.name),h('p','原生属性、技能和说明')]))):null]);}});
const BackpackPanel=defineComponent({__name:'BackpackPanel',props:{backpackEquipment:Array,backpackMaterials:Array,backpackConsumables:Array},setup(props){const active=ref('equipment'),page=ref(1),materialPage=ref(1),consumablePage=ref(1),selling=ref(false),size=2,equipment=computed(()=>props.backpackEquipment.slice((page.value-1)*size,page.value*size)),consumables=computed(()=>props.backpackConsumables.slice((consumablePage.value-1)*size,consumablePage.value*size));watch(active,()=>{page.value=materialPage.value=consumablePage.value=1;});return()=>h('section',{class:'status-card bag-card'},[
 h('header',{class:'bag-header'},[h('h2','背包'),h('button',{class:['bag-icon-btn',{'bag-icon-btn--sell':selling.value}],'aria-label':'出售模式',onClick:()=>selling.value=!selling.value},selling.value?'退出出售':'出售模式')]),
 h('div',{class:'bag-tabs'},['equipment','materials','consumables'].map((kind,index)=>h('button',{class:['bag-tab',{'bag-tab--active':active.value===kind}],onClick:()=>active.value=kind},['装备','素材','消耗品'][index]))),
 selling.value?h('div',{class:'sell-mode-banner'},'出售模式'):null,
 ...['equipment','materials','consumables'].map(kind=>{const full=kind==='equipment'?props.backpackEquipment:kind==='materials'?props.backpackMaterials:props.backpackConsumables,rows=kind==='equipment'?equipment.value:kind==='materials'?full:consumables.value,current=kind==='equipment'?page:kind==='materials'?materialPage:consumablePage;return h('div',{class:'bag-content','data-kind':kind,style:{display:active.value===kind?'':'none'}},[h('div',{class:'bag-grid'},rows.map(item=>h(VTooltip,{key:item.uuid,item,kind,selling:selling.value}))),kind!=='materials'&&full.length>size?h(VPagination,{modelValue:current.value,length:Math.ceil(full.length/size),'onUpdate:modelValue':value=>current.value=value}):null]);})
 ]);}});
const app=createApp({setup(){return()=>h('main',[show.value?h(BackpackPanel,{backpackEquipment:state.backpack.equipment,backpackMaterials:state.backpack.materials,backpackConsumables:state.backpack.consumables}):h('p','背包已关闭')]);}});
app.config.globalProperties.$pinia={_s:new Map([['player',{get statusData(){return state;}}]])};app.mount('#app');
